//! Forward upgrades: numbered, data-preserving steps, run in order by the
//! explicit [`crate::apply`] in one transaction. Step `n` of [`STEPS`] moves
//! a database from version `LANDED_VERSION + n` to the next; the schema
//! description states the shape after the last one, and a fresh database is
//! created directly at [`crate::VERSION`]. A step's structural statements
//! are generated by `Description::changes_from` from the description it
//! upgrades from; only its data transformations are written by hand.

/// One named forward step and the statements that make it.
#[derive(Clone, Copy)]
pub(crate) struct Step {
    pub name: &'static str,
    pub statements: fn() -> Vec<String>,
}

/// The oldest version this build upgrades from: the version of every
/// deployed database when the steps before it were removed.
pub(crate) const LANDED_VERSION: i32 = 40;

/// The steps after [`LANDED_VERSION`], in landing order.
pub(crate) const STEPS: &[Step] = &[
    Step {
        name: "plain_names",
        statements: plain_names,
    },
    Step {
        name: "source_exclusions",
        statements: source_exclusions,
    },
    Step {
        name: "request_outcomes",
        statements: request_outcomes,
    },
    Step {
        name: "derivation_reading_orders",
        statements: derivation_reading_orders,
    },
    Step {
        name: "owned_blob_releases",
        statements: || vec![crate::tables::OWNED_BLOB_RELEASES.into()],
    },
];

fn source_exclusions() -> Vec<String> {
    vec!["ALTER TABLE registry.sources ADD COLUMN exclusion text".into()]
}

/// Renames to plain words: a record's byte offset in its material is its
/// record offset (also in the `core.visible_events` view, whose column a
/// recreated view cannot rename), the database secret is the store secret,
/// the records behind a shown library value are its supporting records, and
/// the trigger that keeps kind prefixes fixed names what it keeps. No row
/// changes.
fn plain_names() -> Vec<String> {
    let mut statements: Vec<String> = [
        "core.events",
        "core.event_tombstones",
        "core.live_locations",
        "raw.failures",
        "core.admission_stage",
    ]
    .iter()
    .map(|table| format!("ALTER TABLE {table} RENAME COLUMN anchor TO record_offset"))
    .collect();
    statements.extend(
        [
            "ALTER TABLE core.events RENAME CONSTRAINT anchor_in_range TO record_offset_in_range",
            "ALTER VIEW core.visible_events RENAME COLUMN anchor TO record_offset",
            "ALTER TABLE core.owner_protocol_key RENAME TO store_secret",
            "ALTER TABLE core.library_shown RENAME COLUMN supporters TO supporting_records",
            "ALTER TRIGGER keep_owner ON registry.kind_prefixes RENAME TO keep_declaring_producer",
        ]
        .map(String::from),
    );
    let keep_definition = crate::tables::KIND_IMMUTABILITY
        .split(";\n")
        .next()
        .expect("the trigger function comes first");
    statements.push(keep_definition.replacen("CREATE FUNCTION", "CREATE OR REPLACE FUNCTION", 1));
    statements.push(crate::sparse_indexes::configuration());
    statements
}

/// Request identities and their results belong to the operation that writes them.
fn request_outcomes() -> Vec<String> {
    vec![
        crate::tables::OPERATION_REQUESTS.into(),
        crate::tables::OPERATION_ROWS.into(),
    ]
}

fn derivation_reading_orders() -> Vec<String> {
    // The step compares its own two table shapes, even after later upgrades.
    let mut after = crate::description::Description::current();
    after.tables = vec![crate::tables::POSITIONS_WITH_READING_ORDERS.into()];
    let mut before = crate::description::Description::current();
    before.tables = vec!["CREATE TABLE derivation.positions (derivation text PRIMARY KEY, commit_seq bigint NOT NULL)".into()];
    let mut statements = after.changes_from(&before);
    // Seed once from every stored reading, including archived/replaced ones.
    // Version selection can have reset a producer before this upgrade.
    statements.push(
        r#"WITH producers AS MATERIALIZED (
        SELECT derivation AS name FROM derivation.positions
        UNION SELECT name FROM registry.derivations WHERE kind='per_event'
    ), selected_runs AS MATERIALIZED (
        SELECT r.id,r.name FROM core.runs r JOIN producers p ON p.name=r.name WHERE r.events>0
    ), maxima AS MATERIALIZED (
        SELECT r.name,max(e.reading_order) AS reading_order
        FROM core.events e JOIN selected_runs r ON r.id=e.run_id
        WHERE EXISTS (SELECT 1 FROM selected_runs) GROUP BY r.name
    )
    INSERT INTO derivation.positions(derivation,commit_seq,reading_order)
    SELECT p.name,coalesce(old.commit_seq,0),coalesce(m.reading_order,0)
    FROM producers p LEFT JOIN derivation.positions old ON old.derivation=p.name
    LEFT JOIN maxima m ON m.name=p.name
    ON CONFLICT(derivation) DO UPDATE SET reading_order=EXCLUDED.reading_order"#
            .into(),
    );
    statements
}
